<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Experience; use Illuminate\Http\Request;
class ExperienceController extends Controller { public function index(){return view('admin.experiences.index',['items'=>Experience::orderBy('sort_order')->get()]);} public function create(){return view('admin.experiences.form',['item'=>new Experience]);} public function store(Request $r){Experience::create($this->data($r));return redirect()->route('admin.experiences.index')->with('success','Pengalaman ditambahkan.');} public function edit(Experience $experience){return view('admin.experiences.form',['item'=>$experience]);} public function update(Request $r,Experience $experience){$experience->update($this->data($r));return redirect()->route('admin.experiences.index')->with('success','Pengalaman diperbarui.');} public function destroy(Experience $experience){$experience->delete();return back()->with('success','Pengalaman dihapus.');} private function data(Request $r):array{return $r->validate(['role'=>'required|string|max:120','company'=>'required|string|max:120','location'=>'nullable|string|max:100','period'=>'required|string|max:100','description'=>'nullable|string|max:2000','sort_order'=>'nullable|integer|min:0']);} }
